          <<"h", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_int64(bytes)
            msg = %{msg | mediaKeyTimestamp: value}
            parse_key_value(rest, msg)

          <<"b", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | packDescription: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"Z", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | contextInfo:
                  case :erlang.map_get(:contextInfo, msg) do
                    nil ->
                      WAWebProtobufsE2E.ContextInfo.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.ContextInfo.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"R", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | caption: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"J", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | directPath: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"B", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | mediaKey: delimited}
            parse_key_value(rest, msg)

          <<":", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | fileEncSHA256: delimited}
            parse_key_value(rest, msg)

          <<"2", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | fileSHA256: delimited}
            parse_key_value(rest, msg)

          <<"(", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | fileLength: value}
            parse_key_value(rest, msg)

          <<"(", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint64(bytes)
            msg = %{msg | fileLength: value}
            parse_key_value(rest, msg)

          <<"\"", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | stickers: [
                  WAWebProtobufsE2E.StickerPackMessage.Sticker.decode!(delimited)
                  | :erlang.map_get(:stickers, msg)
                ]
            }

            parse_key_value(rest, msg)

          <<"\x1A", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | publisher: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\x12", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | name: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\n", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | stickerPackID: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<bytes::binary>> ->
            {tag, wire_type, rest} = Protox.Decode.parse_key(bytes)
            {value, rest} = Protox.Decode.parse_unknown(tag, wire_type, rest)
            msg = %{msg | __uf__: [value | :erlang.map_get(:__uf__, msg)]}
            parse_key_value(rest, msg)
        end
      end
    )
  )

  (
    @spec unknown_fields(struct()) :: [{non_neg_integer(), Protox.Types.tag(), binary()}]
    def unknown_fields(msg), do: msg.__uf__

    @spec unknown_fields_name() :: :__uf__
    def unknown_fields_name(), do: :__uf__

    @spec clear_unknown_fields(struct) :: struct
    def clear_unknown_fields(msg), do: struct!(msg, __uf__: [])
  )

  (
    @spec default(atom()) ::
            {:ok, Protox.Scalar.scalar_default_value_type()}
            | {:error, :no_such_field | :no_default_value}
    def default(field_name), do: Protox.MessageSchema.default(@schema, field_name)
  )
end
